{
  "findings": [
    {
      "check_id": "CKV2_AWS_11",
      "title": "Ensure VPC flow logging is enabled in all VPCs",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "VPC flow logging is not enabled, making it difficult to investigate incidents or identify security issues within the VPC."
    },
    {
      "check_id": "CKV2_AWS_12",
      "title": "Ensure the default security group of every VPC restricts all traffic",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "The default security group of the VPC does not restrict all traffic, potentially allowing unauthorized access."
    }
  ],
  "patched_code": "resource \"aws_vpc\" \"changeme_aws_vpc_simple\" {\n  cidr_block = \"10.1.0.0/16\"\n}\n\nresource \"aws_flow_log\" \"changeme_aws_vpc_simple_flow_log\" {\n  vpc_id = aws_vpc.changeme_aws_vpc_simple.id\n  traffic_type = \"ALL\"\n  log_destination_type = \"cloud-watch-logs\"\n  log_group_name = aws_cloudwatch_log_group.changeme_aws_vpc_simple_flow_log.name\n}\n\nresource \"aws_cloudwatch_log_group\" \"changeme_aws_vpc_simple_flow_log\" {\n  name = \"${aws_vpc.changeme_aws_vpc_simple.id}-flow-logs\"\n}\n\nresource \"aws_default_security_group\" \"changeme_aws_vpc_simple_default_sg\" {\n  vpc_id = aws_vpc.changeme_aws_vpc_simple.id\n  ingress = []\n  egress = []\n}",
  "fix_summary": "Enabled VPC flow logging and restricted the default security group to not allow any traffic."
}
